args.sql:
ALTER TABLE employment_and_income ADD COLUMN fsi NUMERIC(5,3);

DO $$
DECLARE
    r RECORD;
    v_fsi NUMERIC;
BEGIN
    FOR r IN
        SELECT e.emplcoreref, e.debincratio, e.mthincome,
               x.liqassets, x.bankaccbal, x.savamount
        FROM employment_and_income e
        JOIN expenses_and_assets x ON e.emplcoreref = x.expemplref
    LOOP
        v_fsi := 0.3 * (1 - r.debincratio)
               + 0.3 * (r.liqassets / (r.mthincome * 6))
               + 0.2 * (r.bankaccbal / (r.mthincome * 3))
               + 0.2 * (r.savamount / (r.mthincome * 12));
        UPDATE employment_and_income
        SET fsi = v_fsi
        WHERE emplcoreref = r.emplcoreref;
    END LOOP;
END $$;

